<template>
  <div class="rbac-page"><PageHead title="权限管理" desc="目录仅展示已接入的正式页面与操作；权限码和执行绑定由系统登记。"/>
    <RbacModeNotice />
    <section class="panel"><div class="rbac-toolbar"><el-input v-model="search" clearable placeholder="搜索权限名称、权限码或资源" aria-label="搜索权限"/><el-select v-model="moduleFilter" clearable placeholder="全部模块" aria-label="权限模块"><el-option v-for="module in modules" :key="module" :value="module" :label="module"/></el-select><el-select v-model="kindFilter" clearable placeholder="全部权限类型" aria-label="权限类型"><el-option value="page" label="页面权限"/><el-option value="operation" label="操作权限"/></el-select><el-select v-model="enabledFilter" clearable placeholder="全部状态" aria-label="权限状态"><el-option value="enabled" label="启用"/><el-option value="disabled" label="停用"/></el-select><span class="rbac-count">共 {{ filtered.length }} 个已接入权限</span></div><el-alert v-if="pageError" :title="pageError" type="error" :closable="false" class="rbac-error"/>
      <el-table :data="rows" class="rbac-table" empty-text="没有匹配权限"><el-table-column label="权限名称" min-width="210"><template #default="{row}"><strong :data-permission-code="row.code">{{ row.name }}</strong><div class="technical">{{ row.code }}</div></template></el-table-column><el-table-column prop="module" label="模块" min-width="100"/><el-table-column label="资源" min-width="130"><template #default="{row}">{{ resourceLabel(row.resource) }}</template></el-table-column><el-table-column label="类型 / 动作" width="130"><template #default="{row}"><div>{{ row.kind==='page'?'页面访问':'操作' }}</div><span class="technical">{{ actionLabel(row.action) }}</span></template></el-table-column><el-table-column label="路由或操作绑定" min-width="170"><template #default="{row}"><span class="technical">{{ row.route || row.code }}</span></template></el-table-column><el-table-column label="引用角色" width="100" align="right"><template #default="{row}"><el-button link type="primary" @click="showReferences(row)">{{ references(row.code).length }}</el-button></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{ row.enabled?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><div class="rbac-actions"><el-button link type="primary" :disabled="!store.can('system:permission:update')" @click="open(row)">编辑</el-button><el-button link @click="showReferences(row)">引用</el-button></div></template></el-table-column></el-table><div class="rbac-pagination"><el-pagination v-model:current-page="page" :page-size="20" :total="filtered.length" layout="total, prev, pager, next"/></div>
    </section>
    <el-drawer v-model="editOpen" title="编辑内置权限" size="min(540px,95vw)" :before-close="closeEdit" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" class="rbac-error"/><el-form v-if="form" label-position="top" :disabled="busy"><el-form-item label="权限名称" required><el-input v-model="form.name" maxlength="100" aria-label="权限名称"/></el-form-item><el-form-item label="权限码"><el-input :model-value="form.code" readonly aria-label="权限码"/><el-button link type="primary" @click="copyCode">复制权限码</el-button></el-form-item><el-form-item label="执行绑定"><p class="rbac-codes">{{ form.module }} / {{ resourceLabel(form.resource) }} / {{ actionLabel(form.action) }}<br>{{ form.route || '实际 Store 操作' }}</p><p class="rbac-help">身份、权限码、资源和执行绑定由系统维护，不能在此更换。</p></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="500"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled" active-text="启用" inactive-text="停用"/><p class="rbac-help">被业务角色引用的权限需先撤销授权；超级管理员目录中的非恢复权限可停用，恢复路径始终受保护。</p></el-form-item><p v-if="form.dependsOn?.length" class="rbac-help">依赖权限：{{ form.dependsOn.join('、') }}。依赖不会自动授权。</p></el-form><template #footer><el-button :disabled="busy" @click="closeEdit()">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存权限信息</el-button></template></el-drawer>
    <el-drawer v-model="referenceOpen" :title="`引用角色 · ${referencePermission?.name || ''}`" size="min(460px,95vw)"><p class="rbac-help">角色授权请前往角色管理；此处只查看引用。</p><ul class="rbac-reference-list"><li v-for="role in references(referencePermission?.code || '')" :key="role.id"><strong>{{ role.name }}</strong><div class="rbac-codes">{{ role.code }} · {{ role.enabled?'启用':'停用' }}</div></li></ul><el-empty v-if="!references(referencePermission?.code || '').length" description="没有角色引用此权限"/></el-drawer>
  </div>
</template>
<script setup lang="ts">
import RbacModeNotice from '../components/rbac/RbacModeNotice.vue'
import { computed, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { resourceLabel, actionLabel } from '../components/rbac/presentation'
import PageHead from '../components/PageHead.vue'
import { useRbacDraftGuard } from '../components/rbac/useRbacDraftGuard'
import '../components/rbac/admin.css'
import { useCatalogStore } from '../stores/catalog'
import { isRetiredPermission } from '../domain/rbac'
import type { RbacPermission } from '../domain/rbac'
const store=useCatalogStore(),search=ref(''),moduleFilter=ref(''),kindFilter=ref(''),enabledFilter=ref(''),page=ref(1),pageError=ref(''),error=ref(''),busy=ref(false),editOpen=ref(false),referenceOpen=ref(false),initial=ref('')
const form=ref<RbacPermission>(),referencePermission=ref<RbacPermission>()
const permissions=computed(()=>store.data.rbac?.permissions.filter(p=>!isRetiredPermission(p.code)) || []),modules=computed(()=>[...new Set(permissions.value.map(p=>p.module))])
const filtered=computed(()=>permissions.value.filter(p=>(!search.value||`${p.name} ${p.code} ${p.resource}`.toLowerCase().includes(search.value.toLowerCase()))&&(!moduleFilter.value||p.module===moduleFilter.value)&&(!kindFilter.value||p.kind===kindFilter.value)&&(!enabledFilter.value||(p.enabled?'enabled':'disabled')===enabledFilter.value)))
const rows=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20));watch([search,moduleFilter,kindFilter,enabledFilter],()=>page.value=1)
const dirty=computed(()=>editOpen.value&&JSON.stringify(form.value)!==initial.value),{confirmDiscard}=useRbacDraftGuard(dirty)
function references(code:string){return store.data.rbac?.roles.filter(r=>r.permissionCodes.includes(code)) || []}
function showReferences(permission:RbacPermission){referencePermission.value=permission;referenceOpen.value=true}
function open(permission:RbacPermission){form.value=JSON.parse(JSON.stringify(permission));initial.value=JSON.stringify(form.value);error.value='';editOpen.value=true}
async function closeEdit(done?:()=>void){if(busy.value)return;if(await confirmDiscard()){editOpen.value=false;done?.()}}
async function copyCode(){try{await navigator.clipboard.writeText(form.value?.code||'');ElMessage.success('已复制权限码')}catch{ElMessage.info('可在只读权限码输入框选择复制')}}
async function save(){error.value='';if(!form.value?.name.trim()){error.value='请填写权限名称';return}busy.value=true;try{const r=await store.saveRbacPermission(JSON.parse(JSON.stringify(form.value)));if(!r.ok){error.value=r.message||'保存失败，草稿保留';return}initial.value=JSON.stringify(form.value);editOpen.value=false;ElMessage.success('权限信息已保存')}finally{busy.value=false}}
</script>
